CREATE TABLE `velix_clip_suggestions` (`id` text PRIMARY KEY NOT NULL, `project_id` text NOT NULL REFERENCES `video_projects`(`id`) ON DELETE CASCADE, `reference_id` text NOT NULL REFERENCES `velix_media_references`(`id`) ON DELETE CASCADE, `start` real NOT NULL, `end` real NOT NULL, `confidence` real NOT NULL, `criteria` text NOT NULL DEFAULT '[]', `accepted` integer NOT NULL DEFAULT 0, `created_at` text NOT NULL DEFAULT (datetime('now')));
